/** 
 * Calculate maximum message size by given identifier and based on local user's own identity.
 * @param safety Number of chars extra slack as safety measure for resultingvalue. (This may just save you in case of off-by-one errors by an IRC server.)
 * @param identifier the identifier
 * @return Returns number of chars available for message.
 */
private int calculateMaximumMessageSize(final int safety,final String identifier){
  final StringBuilder builder=new StringBuilder(":");
  builder.append(this.identity.getIdentityString());
  builder.append(" PRIVMSG ");
  builder.append(identifier);
  builder.append(" :");
  return IRC_PROTOCOL_MAX_MESSAGE_SIZE - safety - builder.length();
}
